# region: intake
def intake(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: fold
def fold(xs, offset=1):
    return [v - offset for v in xs]

# region: render
def render(xs, offset=1):
    return [v + offset for v in xs]

# region: shape
def shape(xs, floor_=3):
    return [v for v in xs if v >= floor_]

# region: emit
def emit(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: sift
def sift(summary, bar=2):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return sift(emit(shape(render(fold(intake(raw))))))

